/**
 * charclass.mjs -- character classification primitives.
 *
 * Every predicate works on numeric code points only, so the whole tokenizer
 * can be built out of explicit character tests (a hand written scanner)
 * without any pattern matching machinery.
 */

/** Code points that Python treats as whitespace (str.isspace / re "\s"). */
const SPACE_CODES = [
  0x1c, 0x1d, 0x1e, 0x1f, // file/group/record/unit separators
  0x20, // space
  0x85, // next line
  0xa0, // no-break space
  0x1680, // ogham space mark
  0x2028, // line separator
  0x2029, // paragraph separator
  0x202f, // narrow no-break space
  0x205f, // medium mathematical space
  0x3000, // ideographic space
];

/** Latin-1 code points that are punctuation/symbols rather than word chars. */
const LATIN1_NON_WORD = [
  0xa1, 0xa2, 0xa3, 0xa4, 0xa5, 0xa6, 0xa7, 0xa8, 0xa9,
  0xab, 0xac, 0xad, 0xae, 0xaf, 0xb0, 0xb1,
  0xb4, 0xb6, 0xb7, 0xb8, 0xbb, 0xbf,
  0xd7, 0xf7,
];

function inList(list, cp) {
  for (let k = 0; k < list.length; k += 1) {
    if (list[k] === cp) return true;
  }
  return false;
}

export function isSpace(cp) {
  if (cp === -1) return false;
  if (cp >= 0x09 && cp <= 0x0d) return true;
  if (cp >= 0x2000 && cp <= 0x200a) return true;
  return inList(SPACE_CODES, cp);
}

export function isDigit(cp) {
  return cp >= 0x30 && cp <= 0x39;
}

export function isAsciiLetter(cp) {
  return (cp >= 0x41 && cp <= 0x5a) || (cp >= 0x61 && cp <= 0x7a);
}

/**
 * The class sqlparse spells `[A-ZÀ-Ü]`.  Its patterns are compiled with the
 * ignore-case flag, so the lower half of Latin-1 counts as well.
 */
export function isNameStart(cp) {
  if (isAsciiLetter(cp)) return true;
  if (cp >= 0xc0 && cp <= 0xdc) return true;
  if (cp >= 0xe0 && cp <= 0xfc) return true;
  return false;
}

/** Python's `\w`: letters, digits, underscore -- Unicode aware. */
export function isWord(cp) {
  if (cp === -1) return false;
  if (isDigit(cp) || isAsciiLetter(cp) || cp === 0x5f) return true;
  if (cp < 0x80) return false;
  if (isSpace(cp)) return false;
  if (inList(LATIN1_NON_WORD, cp)) return false;
  if (cp >= 0x2000 && cp <= 0x206f) return false; // general punctuation
  return true;
}

/** Start of an identifier body: `\w` plus the `$`/`#` extensions. */
export function isIdentBody(cp) {
  return isWord(cp) || cp === 0x24 || cp === 0x23;
}

/** ASCII (plus Latin-1) upper casing, matching str.upper() for keywords. */
export function upper(text) {
  let out = '';
  for (let i = 0; i < text.length; i += 1) {
    const cp = text.charCodeAt(i);
    if (cp >= 0x61 && cp <= 0x7a) {
      out += String.fromCharCode(cp - 32);
    } else if (cp >= 0xe0 && cp <= 0xfe && cp !== 0xf7) {
      out += String.fromCharCode(cp - 32);
    } else {
      out += text[i];
    }
  }
  return out;
}

/** Code point at `i`, or -1 when out of range. */
export function codeAt(text, i) {
  if (i < 0 || i >= text.length) return -1;
  return text.charCodeAt(i);
}

/** True when `text` contains `needle` starting at `i`. */
export function hasAt(text, i, needle) {
  if (i + needle.length > text.length) return false;
  for (let k = 0; k < needle.length; k += 1) {
    if (text.charCodeAt(i + k) !== needle.charCodeAt(k)) return false;
  }
  return true;
}

/** Case-insensitive variant of hasAt for ASCII literals. */
export function hasAtFolded(text, i, needle) {
  if (i + needle.length > text.length) return false;
  for (let k = 0; k < needle.length; k += 1) {
    let a = text.charCodeAt(i + k);
    let b = needle.charCodeAt(k);
    if (a >= 0x61 && a <= 0x7a) a -= 32;
    if (b >= 0x61 && b <= 0x7a) b -= 32;
    if (a !== b) return false;
  }
  return true;
}

/** Index of `needle` in `text` at or after `from`, or -1. */
export function indexOfFrom(text, needle, from) {
  const limit = text.length - needle.length;
  for (let i = from; i <= limit; i += 1) {
    if (hasAt(text, i, needle)) return i;
  }
  return -1;
}

