/**
 * tokentypes.mjs -- the token type lattice.
 *
 * sqlparse inherits pygments' token types: every type is a node in a tree and
 * `ttype in T.Keyword` is a *subtree* test, while `ttype is T.Keyword` is an
 * identity test.  The statement splitter relies on both flavours (and on the
 * fact that a tuple membership test such as `ttype in (T.Whitespace, ...)`
 * compares for equality, so `Newline` does *not* belong to it), so both are
 * modelled explicitly here.
 */

const registry = new Map();

function makeType(path) {
  const existing = registry.get(path);
  if (existing !== undefined) return existing;
  const type = Object.freeze({ path });
  registry.set(path, type);
  return type;
}

/** Identity test -- mirrors `ttype is Other`. */
export function isExactly(ttype, other) {
  return ttype === other;
}

/** Subtree test -- mirrors `ttype in Other`. */
export function isKindOf(ttype, other) {
  if (ttype === other) return true;
  const { path } = ttype;
  const prefix = other.path;
  if (path.length <= prefix.length) return false;
  for (let i = 0; i < prefix.length; i += 1) {
    if (path.charCodeAt(i) !== prefix.charCodeAt(i)) return false;
  }
  return path.charCodeAt(prefix.length) === 0x2e; // '.'
}

/**
 * Equality test against a tuple of types -- mirrors `ttype in (a, b)`, which
 * in Python compares element-wise and therefore ignores the hierarchy.
 */
export function isOneOf(ttype, types) {
  for (let i = 0; i < types.length; i += 1) {
    if (types[i] === ttype) return true;
  }
  return false;
}

export const T = Object.freeze({
  Error: makeType('Token.Error'),
  Text: makeType('Token.Text'),
  Whitespace: makeType('Token.Text.Whitespace'),
  Newline: makeType('Token.Text.Whitespace.Newline'),

  Comment: makeType('Token.Comment'),
  CommentSingle: makeType('Token.Comment.Single'),
  CommentSingleHint: makeType('Token.Comment.Single.Hint'),
  CommentMultiline: makeType('Token.Comment.Multiline'),
  CommentMultilineHint: makeType('Token.Comment.Multiline.Hint'),

  Keyword: makeType('Token.Keyword'),
  KeywordDML: makeType('Token.Keyword.DML'),
  KeywordDDL: makeType('Token.Keyword.DDL'),
  KeywordCTE: makeType('Token.Keyword.CTE'),
  KeywordTZCast: makeType('Token.Keyword.TZCast'),

  Name: makeType('Token.Name'),
  NameBuiltin: makeType('Token.Name.Builtin'),
  NamePlaceholder: makeType('Token.Name.Placeholder'),
  NameQuoted: makeType('Token.Name.Quoted'),

  Literal: makeType('Token.Literal'),
  StringSingle: makeType('Token.Literal.String.Single'),
  StringSymbol: makeType('Token.Literal.String.Symbol'),
  NumberInteger: makeType('Token.Literal.Number.Integer'),
  NumberFloat: makeType('Token.Literal.Number.Float'),

  Operator: makeType('Token.Operator'),
  OperatorComparison: makeType('Token.Operator.Comparison'),
  Punctuation: makeType('Token.Punctuation'),
  Wildcard: makeType('Token.Wildcard'),
  Assignment: makeType('Token.Assignment'),
  Command: makeType('Token.Command'),
});

