/**
 * keywords.mjs -- keyword classification tables.
 *
 * Only a handful of keywords actually influence how a script is cut into
 * statements (BEGIN/END/DECLARE/IF/FOR/WHILE/CASE/TRANSACTION/WORK/GO and the
 * CREATE family).  The remaining entries exist so that the token stream this
 * lexer produces carries the same types as the reference implementation.
 */

import { T } from './tokentypes.mjs';

/**
 * Words that are recognised before the identifier rules, and therefore stay
 * keywords even when directly followed by `(`.
 */
export const EARLY_KEYWORDS = ['CASE', 'IN', 'VALUES', 'USING', 'FROM', 'AS'];

/**
 * Multi word keywords, matched as `WORD (\s+ WORD)+` followed by a word
 * boundary.  Longer sequences are attempted first.
 */
export const PHRASE_KEYWORDS = [
  { words: ['LEFT', 'OUTER', 'JOIN'], ttype: T.Keyword },
  { words: ['RIGHT', 'OUTER', 'JOIN'], ttype: T.Keyword },
  { words: ['FULL', 'OUTER', 'JOIN'], ttype: T.Keyword },
  { words: ['LEFT', 'INNER', 'JOIN'], ttype: T.Keyword },
  { words: ['RIGHT', 'INNER', 'JOIN'], ttype: T.Keyword },
  { words: ['CROSS', 'JOIN'], ttype: T.Keyword },
  { words: ['NATURAL', 'JOIN'], ttype: T.Keyword },
  { words: ['INNER', 'JOIN'], ttype: T.Keyword },
  { words: ['OUTER', 'JOIN'], ttype: T.Keyword },
  { words: ['STRAIGHT', 'JOIN'], ttype: T.Keyword },
  { words: ['LEFT', 'JOIN'], ttype: T.Keyword },
  { words: ['RIGHT', 'JOIN'], ttype: T.Keyword },
  { words: ['FULL', 'JOIN'], ttype: T.Keyword },
  { words: ['NOT', 'NULL'], ttype: T.Keyword },
  { words: ['NULLS', 'FIRST'], ttype: T.Keyword },
  { words: ['NULLS', 'LAST'], ttype: T.Keyword },
  { words: ['UNION', 'ALL'], ttype: T.Keyword },
  { words: ['GROUP', 'BY'], ttype: T.Keyword },
  { words: ['ORDER', 'BY'], ttype: T.Keyword },
  { words: ['HANDLER', 'FOR'], ttype: T.Keyword },
  { words: ['DOUBLE', 'PRECISION'], ttype: T.NameBuiltin },
];

/**
 * `END`, optionally glued to IF / LOOP / WHILE.  The suffix is part of the
 * token value, whitespace included, which is why `END  IF` (two blanks) is a
 * different keyword than `END IF`.
 */
export const END_SUFFIXES = ['IF', 'LOOP', 'WHILE'];

const SINGLE_KEYWORDS = new Map();

function register(ttype, words) {
  for (let i = 0; i < words.length; i += 1) {
    SINGLE_KEYWORDS.set(words[i], ttype);
  }
}

register(T.KeywordDML, [
  'SELECT', 'INSERT', 'UPDATE', 'DELETE', 'REPLACE', 'MERGE', 'UPSERT',
]);

register(T.KeywordDDL, [
  'DROP', 'ALTER', 'TRUNCATE', 'RENAME', 'COMMENT',
]);

register(T.KeywordCTE, ['WITH']);

register(T.Keyword, [
  // block and control flow structure -- these drive the split level
  'BEGIN', 'DECLARE', 'IF', 'ELSE', 'ELSIF', 'ELSEIF', 'THEN', 'WHEN',
  'FOR', 'WHILE', 'LOOP', 'REPEAT', 'UNTIL', 'DO', 'EXCEPTION', 'RETURN',
  'TRANSACTION', 'WORK', 'ATOMIC', 'TRY', 'CATCH',
  // ordinary statement vocabulary
  'ADD', 'AFTER', 'ALL', 'AND', 'ANY', 'ASC', 'BEFORE', 'BETWEEN', 'BOTH',
  'BY', 'CASCADE', 'CHECK', 'COLUMN', 'COMMIT', 'CONSTRAINT', 'CURSOR',
  'DATABASE', 'DEFAULT', 'DESC', 'DISTINCT', 'EACH', 'ELSEWHERE', 'ESCAPE',
  'EXCEPT', 'EXISTS', 'EXPLAIN', 'FETCH', 'FIRST', 'FOREIGN', 'FUNCTION',
  'GRANT', 'GROUP', 'HAVING', 'IDENTITY', 'IGNORE', 'INDEX', 'INNER', 'INTO',
  'IS', 'ISNULL', 'JOIN', 'KEY', 'LANGUAGE', 'LAST', 'LEFT', 'LIMIT', 'MODIFY',
  'NATURAL', 'NEXT', 'NO', 'NOT', 'NOTNULL', 'NULL', 'OF', 'OFFSET', 'ON',
  'ONLY', 'OPTION', 'OR', 'ORDER', 'OUTER', 'OVER', 'PACKAGE', 'PARTITION',
  'PRECISION', 'PRIMARY', 'PROCEDURE', 'PUBLIC', 'REFERENCES', 'RESTRICT',
  'RETURNS', 'REVOKE', 'RIGHT', 'ROLLBACK', 'ROW', 'ROWS', 'SAVEPOINT',
  'SCHEMA', 'SEQUENCE', 'SET', 'SHOW', 'SOME', 'START', 'TABLE', 'TEMPORARY',
  'TO', 'TRIGGER', 'UNION', 'UNIQUE', 'UNSIGNED', 'USE', 'VIEW', 'WHERE',
  'WINDOW', 'WITHOUT',
]);

/**
 * Classify a bare identifier: keyword tables first, plain name otherwise.
 * The original spelling is preserved -- the splitter compares GO case
 * sensitively, so the value must never be normalised.
 */
export function classifyWord(uppercased) {
  const ttype = SINGLE_KEYWORDS.get(uppercased);
  return ttype === undefined ? T.Name : ttype;
}

