  classifyWord, EARLY_KEYWORDS, END_SUFFIXES, PHRASE_KEYWORDS,
} from './keywords.mjs';

const CH_HASH = 0x23;
const CH_DOLLAR = 0x24;
const CH_PERCENT = 0x25;
const CH_QUOTE = 0x27;
const CH_LPAREN = 0x28;
const CH_RPAREN = 0x29;
const CH_STAR = 0x2a;
const CH_MINUS = 0x2d;
const CH_DOT = 0x2e;
const CH_COLON = 0x3a;
const CH_QUESTION = 0x3f;
const CH_AT = 0x40;
const CH_LBRACKET = 0x5b;
const CH_BACKSLASH = 0x5c;
const CH_RBRACKET = 0x5d;
const CH_UNDERSCORE = 0x5f;
const CH_BACKTICK = 0x60;
const CH_DQUOTE = 0x22;
const CH_ACUTE = 0xb4;
const CH_CR = 0x0d;
const CH_LF = 0x0a;

const PUNCTUATION_CHARS = [0x3b, 0x3a, 0x28, 0x29, 0x5b, 0x5d, 0x2c, 0x2e];
const COMPARISON_CHARS = [0x3c, 0x3e, 0x3d, 0x7e, 0x21];
const OPERATOR_CHARS = [0x2b, 0x2f, 0x40, 0x23, 0x25, 0x5e, 0x26, 0x7c, 0x2d];

function inSet(set, cp) {
  for (let k = 0; k < set.length; k += 1) {
    if (set[k] === cp) return true;
  }
  return false;
}

/** Consume one line terminator; returns its length (0 when absent). */
function eolLength(text, i) {
  const cp = codeAt(text, i);
  if (cp === CH_CR) return codeAt(text, i + 1) === CH_LF ? 2 : 1;
  if (cp === CH_LF) return 1;
  return 0;
