    while (j < text.length) {
      const cp = text.charCodeAt(j);
      if (cp === CH_RBRACKET || cp === CH_LBRACKET) break;
      j += 1;
    }
    if (j === i + 1 || codeAt(text, j) !== CH_RBRACKET) return null;
    return { ttype: T.Name, length: j + 1 - i };
  },
  function phraseKeyword(text, i) {
    for (let k = 0; k < PHRASE_KEYWORDS.length; k += 1) {
      const entry = PHRASE_KEYWORDS[k];
      const length = matchPhrase(text, i, entry.words);
      if (length > 0) return { ttype: entry.ttype, length };
    }
    return null;
  },
  function endKeyword(text, i) {
    const length = matchEndKeyword(text, i);
    return length < 0 ? null : { ttype: T.Keyword, length };
  },
  function createKeyword(text, i) {
    const length = matchCreateKeyword(text, i);
    return length < 0 ? null : { ttype: T.KeywordDDL, length };
  },
  function goKeyword(text, i) {
    const length = matchGoKeyword(text, i);
    return length < 0 ? null : { ttype: T.Keyword, length };
  },
  function identifier(text, i) {
    if (!isWord(codeAt(text, i))) return null;
    let j = i + 1;
    while (isIdentBody(codeAt(text, j))) j += 1;
    const value = text.slice(i, j);
    return { ttype: classifyWord(upper(value)), length: j - i };
  },
  function punctuation(text, i) {
    return inSet(PUNCTUATION_CHARS, codeAt(text, i))
      ? { ttype: T.Punctuation, length: 1 }
      : null;
  },
  function comparison(text, i) {
    let j = i;
    while (inSet(COMPARISON_CHARS, codeAt(text, j))) j += 1;
    return j === i ? null : { ttype: T.OperatorComparison, length: j - i };
  },
  function operator(text, i) {
    let j = i;
    while (inSet(OPERATOR_CHARS, codeAt(text, j))) j += 1;
    return j === i ? null : { ttype: T.Operator, length: j - i };
  },
];

/**
 * Turn `text` into a flat list of `{ ttype, value }` tokens.  Anything no rule
 * accepts becomes a one character error token, exactly as upstream does.
 */
export function tokenize(text) {
  const tokens = [];
  let i = 0;
  while (i < text.length) {
    let matched = null;
    for (let r = 0; r < RULES.length; r += 1) {
      matched = RULES[r](text, i);
      if (matched !== null && matched.length > 0) break;
      matched = null;
    }
    if (matched === null) {
      tokens.push({ ttype: T.Error, value: text[i] });
      i += 1;
      continue;
    }
    tokens.push({ ttype: matched.ttype, value: text.slice(i, i + matched.length) });
    i += matched.length;
  }
  return tokens;
}

