/**
 * statement_splitter.mjs -- cuts a token stream into statements.
 *
 * The rules were recovered from the reference behaviour:
 *
 *  - `;` ends a statement whenever the current split level is <= 0, and so
 *    does a `GO` (optionally `GO <n>`) batch separator.
 *  - after a terminator, blanks and `--` line comments still belong to the
 *    statement just closed; a newline or a block comment does not.
 *  - `BEGIN` opens a block, but only once a real token other than `;`,
 *    `TRANSACTION` or `WORK` follows it -- `BEGIN;` and `BEGIN TRANSACTION;`
 *    are statements in their own right.
 *  - `END` closes a block; inside `CREATE ...` bodies `DECLARE` and the
 *    `IF`/`FOR`/`WHILE`/`CASE` constructs open one too.
 */

import { upper } from './charclass.mjs';
import { isExactly, isKindOf, isOneOf, T } from './tokentypes.mjs';

/**
 * Token types that may trail a statement terminator.  Upstream compares
 * against a plain tuple, which is an equality test -- newlines live in a
 * *subtype* of Whitespace and therefore do not qualify.
 */
const TRAILING_TYPES = [T.Whitespace, T.CommentSingle];

const BLOCK_OPENERS = ['IF', 'FOR', 'WHILE', 'CASE'];
const BLOCK_CLOSERS = ['END IF', 'END FOR', 'END WHILE'];

function isTrailing(ttype) {
  return isOneOf(ttype, TRAILING_TYPES);
}

function isFiller(ttype) {
  return isKindOf(ttype, T.Whitespace) || isKindOf(ttype, T.Comment);
}

function includesWord(list, word) {
  for (let i = 0; i < list.length; i += 1) {
    if (list[i] === word) return true;
  }
  return false;
}

function startsWithCreate(value) {
  return value.length >= 6 && value.slice(0, 6) === 'CREATE';
}

/** Equivalent of `value.split()[0]`. */
function firstWord(value) {
  let start = 0;
  while (start < value.length && isBlank(value.charCodeAt(start))) start += 1;
  let end = start;
  while (end < value.length && !isBlank(value.charCodeAt(end))) end += 1;
  return value.slice(start, end);
}

function isBlank(cp) {
  return cp === 0x20 || (cp >= 0x09 && cp <= 0x0d);
}

export class StatementSplitter {
  constructor() {
    this.statements = [];
    this.reset();
  }

  reset() {
    this.tokens = [];
    this.level = 0;
    this.beginDepth = 0;
    this.isCreate = false;
    this.inCase = false;
    this.pendingBegin = false;
    this.consumeTrailing = false;
  }

  /** `BEGIN` only raises the level once a real token follows it. */
  resolvePendingBegin(token) {
    if (!this.pendingBegin) return;
    this.pendingBegin = false;
    if (isExactly(token.ttype, T.Punctuation) && token.value === ';') return;
    if (isKindOf(token.ttype, T.Keyword)) {
      const word = upper(token.value);
      if (word === 'TRANSACTION' || word === 'WORK') {
        this.beginDepth += 1;
        return;
      }
    }
    this.level += 1;
    this.beginDepth += 1;
  }

  changeLevel(token) {
    if (!isKindOf(token.ttype, T.Keyword)) return;
    const word = upper(token.value);

    if (isExactly(token.ttype, T.KeywordDDL) && startsWithCreate(word)) {
      this.isCreate = true;
      return;
    }
    if (word === 'DECLARE' && this.isCreate && this.beginDepth === 0) {
      this.level += 1;
      return;
    }
    if (word === 'BEGIN') {
      this.pendingBegin = true;
      return;
    }
    if (word === 'END') {
      if (this.inCase) this.inCase = false;
      else this.beginDepth = this.beginDepth > 0 ? this.beginDepth - 1 : 0;
      this.level -= 1;
      return;
    }
    if (includesWord(BLOCK_OPENERS, word) && this.isCreate && this.beginDepth > 0) {
      if (word === 'CASE') this.inCase = true;
      this.level += 1;
      return;
    }
    if (includesWord(BLOCK_CLOSERS, word) && !this.inCase
        && this.level > this.beginDepth) {
      this.level -= 1;
    }
  }

  isTerminator(token) {
    if (isExactly(token.ttype, T.Punctuation) && token.value === ';') {
      return this.level <= 0;
    }
    // `GO` is a batch separator, and it is matched case sensitively.
    return isExactly(token.ttype, T.Keyword) && firstWord(token.value) === 'GO';
  }

  flush() {
    let value = '';
    for (let i = 0; i < this.tokens.length; i += 1) value += this.tokens[i].value;
    this.statements.push(value);
  }

  /** True when the buffered statement is nothing but blanks. */
  isBufferBlank() {
    for (let i = 0; i < this.tokens.length; i += 1) {
      if (!isKindOf(this.tokens[i].ttype, T.Whitespace)) return false;
    }
    return true;
  }

  process(tokens) {
    for (let i = 0; i < tokens.length; i += 1) {
      const token = tokens[i];

      if (this.consumeTrailing && !isTrailing(token.ttype)) {
        this.flush();
        this.reset();
      }

      if (!isFiller(token.ttype)) {
        this.resolvePendingBegin(token);
        this.changeLevel(token);
      }

      this.tokens.push(token);

      if (this.isTerminator(token)) this.consumeTrailing = true;
    }

    if (this.tokens.length > 0 && !this.isBufferBlank()) this.flush();
    return this.statements;
  }
}

/** Split a token list into the raw text of each statement. */
export function splitStatements(tokens) {
  return new StatementSplitter().process(tokens);
}

